<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Mail};
use Illuminate\Validation\Rules\Password;
use App\Services\{Support,Registration};
class CompanyRegistrationController extends Controller {
 public function form(){if(in_array(request('type'),['rider','driver']))return app(PublicCourierController::class)->form();return view('guest-tools',['title'=>'Register sorting center','forms'=>[['label'=>'Sorting center registration','action'=>'/register','fields'=>['first_name','last_name','email:email','phone','business_name','sec_number','tin','region','province','city','barangay','street','postal_code','id_document:file','sec_document:file','bir_document:file','password:password','password_confirmation:password','terms:checkbox']]]]);}
 public function register(Request $r){$r->merge(['email'=>mb_strtolower(trim((string)$r->email)),'phone'=>Registration::normalizePhone((string)$r->phone),'business_name'=>trim((string)$r->business_name),'sec_number'=>strtoupper(trim((string)$r->sec_number))]);
  $name=['required','string','min:2','max:50',"regex:/^[\p{L}\p{M} .'-]+$/u"];
  $v=$r->validate(['first_name'=>$name,'last_name'=>$name,'email'=>'required|email|unique:users,email','phone'=>['required','regex:/^09[0-9]{9}$/','unique:users,phone_normalized'],'business_name'=>'required|string|min:3|max:180','sec_number'=>['required','regex:/^[A-Z]{2}[0-9]{9}$/','unique:users,sec_number'],'tin'=>['required','regex:/^[0-9]{3}-[0-9]{3}-[0-9]{3}-[0-9]{3}$/','unique:users,tin'],'region'=>'required|string|max:120','province'=>'required|string|max:120','city'=>'required|string|max:120','barangay'=>'required|string|max:120','street'=>'required|string|max:200','postal_code'=>['required','regex:/^[0-9]{4}$/'],'id_document'=>'required|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120','sec_document'=>'required|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120','bir_document'=>'required|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120','password'=>['required','confirmed',Password::min(8)->mixedCase()->numbers()->symbols()],'terms'=>'accepted']);
  \App\Services\Geography::validate($v);$territory=\App\Services\Municipalities::key($v['province'],$v['city']);if(DB::table('sorting_centers')->where('municipality_key',$territory)->exists())Support::fail('city','This municipality already has a sorting center. Choose another municipality.');$norm=mb_strtolower($v['business_name']);if(DB::table('sorting_centers')->whereRaw('LOWER(TRIM(name)) = ?',[$norm])->exists())Support::fail('business_name','Company name is already registered.');
  $paths=[];try{$id=DB::transaction(function()use($v,$r,$norm,$territory,&$paths){$id=\App\Services\PendingRegistration::user(['name'=>$v['first_name'].' '.$v['last_name'],'first_name'=>$v['first_name'],'last_name'=>$v['last_name'],'email'=>$v['email'],'phone'=>$v['phone'],'phone_normalized'=>$v['phone'],'password'=>Hash::make($v['password']),'role'=>'sorting_center','approval_status'=>'unverified','verification_required'=>1,'active'=>1,'tin'=>$v['tin'],'sec_number'=>$v['sec_number'],'service_areas'=>json_encode([$v['city']]),'region'=>$v['region'],'terms_accepted_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);\App\Services\PendingRegistration::related('sorting_centers',['user_id'=>$id,'name'=>$v['business_name'],'name_normalized'=>$norm,'municipality_key'=>$territory,'city'=>$v['city'],'province'=>$v['province'],'created_at'=>now(),'updated_at'=>now()]);\App\Services\PendingRegistration::related('addresses',['user_id'=>$id,'recipient'=>$v['first_name'].' '.$v['last_name'],'phone'=>$v['phone'],'street'=>$v['street'],'province'=>$v['province'],'city'=>$v['city'],'barangay'=>$v['barangay'],'postal_code'=>$v['postal_code'],'is_default'=>1,'created_at'=>now(),'updated_at'=>now()]);foreach(['id_document','sec_document','bir_document'] as $f){$path=$r->file($f)->store('documents','local');$paths[]=$path;\App\Services\PendingRegistration::related('registration_documents',['user_id'=>$id,'kind'=>$f,'path'=>$path,'created_at'=>now(),'updated_at'=>now()]);}Registration::issueOtp($id,$v['email']);return $id;});}catch(\Throwable $e){foreach($paths as $path)\Illuminate\Support\Facades\Storage::disk('local')->delete($path);if($e instanceof \Illuminate\Database\UniqueConstraintViolationException)Support::fail('city','This municipality or these account details were just registered. Refresh and choose another municipality.');throw $e;}$r->session()->regenerate();$r->session()->put('company_pending_registration_id',$id);return redirect('/company/verify')->with('success','Check your email for a 6-digit code.');
 }
 public function verifyForm(){return view('guest-tools',['title'=>'Verify account email','forms'=>[['label'=>'Verify OTP','action'=>'/company/verify','fields'=>['otp']],['label'=>'Resend OTP','action'=>'/company/resend','fields'=>[]]]]);}
 public function verify(Request $r){$v=$r->validate(['otp'=>['required','regex:/^[0-9]{6}$/']]);$id=$r->session()->get('company_pending_registration_id');$error=\App\Services\PendingRegistration::verify((int)$id,$v['otp']);if($error)Support::fail('otp',$error);$r->session()->forget('company_pending_registration_id');return redirect('/login')->with('success',DB::table('users')->where('id',$id)->value('role')==='rider'?'Email verified; wait for your municipality sorting center to approve your application.':'Email verified; wait for logistics administrator approval.');}
 public function resend(Request $r){$id=$r->session()->get('company_pending_registration_id');$u=\App\Services\PendingRegistration::applicant($id);Registration::issueOtp($id,$u->email);return back()->with('success','New code sent.');}
}
